// =====================================================================
// FACTORY CONFIG - ศูนย์รวมค่าตั้งค่าของโรงงานทั้งหมด
//
// วิธีแก้ค่า (เลือกอย่างใดอย่างหนึ่ง):
//   1. แก้ตัวเลข/ข้อความใน DEFAULTS ข้างล่างนี้ตรง ๆ (ง่ายสุด ใช้ได้ทุกแพลน)
//   2. หรือตั้งใน n8n Variables (Settings > Variables) ชื่อเดียวกัน - จะทับ DEFAULTS
//   3. หรือตั้ง environment variable (เฉพาะ self-hosted) - จะทับ DEFAULTS เช่นกัน
//
// แก้ที่ workflow 01 ตัวเดียวพอ: sub-workflow ทุกตัวรับ cfg ต่อจากแม่อัตโนมัติ
// =====================================================================
const DEFAULTS = {
  "OPENAI_MODEL_TEXT": "gpt-4.1",
  "GEMINI_API_BASE": "https://generativelanguage.googleapis.com",
  "GEMINI_MODEL_TEXT": "gemini-flash-latest",
  "OPENAI_MODEL_IMAGE": "gpt-image-1",
  "OPENAI_IMAGE_QUALITY": "high",
  "IMAGE_QUALITY_COVER": "high",
  "IMAGE_QUALITY_PAGE": "medium",
  "IMAGE_QUALITY_SMALL": "low",
  "GENERATE_SEPARATE_PREVIEWS": "false",
  "PROMPT_VERSION": "v1.0.0",
  "ETSY_API_BASE": "https://openapi.etsy.com",
  "ETSY_API_KEY": "",
  "ETSY_REFRESH_TOKEN": "",
  "ETSY_SHOP_ID": "",
  "ETSY_LISTING_STATE": "draft",
  "ETSY_TAXONOMY_ID": 2078,
  "GDRIVE_ROOT_FOLDER_ID": "root",
  "DB_TYPE": "postgres",
  "DB_SQLITE_PATH": "/home/node/.n8n/adpf.db",
  "FACTORY_ROTATION": "planner,printable,canva,wallart,resume,spreadsheet,kids,svg",
  "ALERT_WEBHOOK_URL": "",
  "IDEA_TARGET_COUNT": 120,
  "IDEA_BATCH_SIZE": 40,
  "DUPLICATE_SIMILARITY_THRESHOLD": 0.62,
  "ALLOW_PRODUCT_REVISION": "false",
  "BUDGET_DAILY_USD": 20,
  "BUDGET_MONTHLY_USD": 300,
  "BUDGET_RUN_RESERVE_USD": 3,
  "OPENAI_IMAGE_UNIT_COST_USD": 0.19,
  "OPENAI_CHAT_RUN_COST_USD": 0.12,
  "OPENAI_PRICE_OVERRIDE_JSON": "{}",
  "LEARNING_WINDOW_DAYS": 30,
  "LEARNING_MIN_SAMPLE": 15,
  "AB_MIN_VIEWS_PER_ARM": 200,
  "AB_MIN_RELATIVE_LIFT": 0.2
};

const first = $input.first();
const incoming = first && first.json ? first.json : {};
const parentCfg = incoming.cfg && typeof incoming.cfg === 'object' ? incoming.cfg : {};

// ทั้ง $vars และ $env อาจไม่มีอยู่เลย (n8n Cloud) - แตะผ่าน try เท่านั้น
const readVars = (key) => {
  try {
    if (typeof $vars !== 'undefined' && $vars[key] !== undefined && $vars[key] !== '') {
      return $vars[key];
    }
  } catch (e) { /* Variables not available on this plan */ }
  return undefined;
};
const readEnv = (key) => {
  try {
    if (typeof $env !== 'undefined' && $env[key] !== undefined && $env[key] !== '') {
      return $env[key];
    }
  } catch (e) { /* env access blocked or not present */ }
  return undefined;
};

const cfg = {};
const sources = {};
for (const key of Object.keys(DEFAULTS)) {
  if (parentCfg[key] !== undefined) { cfg[key] = parentCfg[key]; sources[key] = 'parent'; continue; }
  const fromVars = readVars(key);
  if (fromVars !== undefined) { cfg[key] = fromVars; sources[key] = 'variables'; continue; }
  const fromEnv = readEnv(key);
  if (fromEnv !== undefined) { cfg[key] = fromEnv; sources[key] = 'env'; continue; }
  cfg[key] = DEFAULTS[key]; sources[key] = 'default';
}

return $input.all().map((item) => ({
  json: { ...item.json, cfg, cfg_sources: sources },
  binary: item.binary,
}));

// Central prompt library. Every OpenAI agent used by this workflow lives
// here so prompts are versioned with the workflow itself and can be
// diffed in git (mirrored in prompts/*.md).
const PROMPT_VERSION = $('Factory Config').first().json.cfg.PROMPT_VERSION || 'v1.0.0';
const PROMPTS = {
  "research_ai": {
    "id": "research_ai",
    "title": "Research AI",
    "purpose": "Turn raw Etsy marketplace signals into one validated product concept.",
    "system": "You are Research AI, a senior Etsy marketplace analyst for a digital product studio.
You only analyse digital (instant download) products. You never invent statistics:
every number you output must be derived from the MARKET SIGNALS block supplied by
the user, or explicitly marked as an estimate inside `_estimates`.

Method, in order:
1. Read the market signals (titles, tags, prices, listing ages, competitor counts).
2. Group listings into micro-niches and score each one on demand vs. saturation.
3. Reject niches that need trademarks, licensed characters, or real brand names.
4. Reject niches that a solo studio cannot produce as a printable/digital file.
5. Pick the single best remaining micro-niche and describe it precisely.

Rules:
- `keyword` must be a real buyer search phrase, 2-5 words, lowercase.
- `sub_keywords` must be 8-15 distinct long-tail phrases, lowercase, no duplicates,
  each <= 20 characters so they can be reused as Etsy tags.
- `difficulty` is one of "easy" | "medium" | "hard" and reflects competition, not
  production effort.
- `selling_points` are buyer-facing benefits, not feature lists.
- Output valid JSON only. No markdown, no commentary.",
    "user_template": "FACTORY: {{factory}}
RUN ID: {{run_id}}
SEED KEYWORD: {{seed_keyword}}

MARKET SIGNALS (from Etsy Open API v3):
{{market_signals_json}}

Produce one product concept for the {{factory}} factory that fits the market gap
you identified. Answer with the exact JSON contract.",
    "output_contract": "{
  "product_type": "string",
  "category": "string",
  "target_customer": "string",
  "keyword": "string",
  "sub_keywords": ["string"],
  "difficulty": "easy|medium|hard",
  "selling_points": ["string"],
  "price_suggestion_usd": 0,
  "market_gap": "string",
  "rejected_ideas": ["string"]
}"
  },
  "seo_ai": {
    "id": "seo_ai",
    "title": "SEO AI",
    "purpose": "Produce Etsy-compliant title, description and tags.",
    "system": "You are SEO AI, an Etsy search optimisation specialist.

Hard Etsy limits you must never break:
- Title: max 140 characters, primary keyword inside the first 40 characters,
  no ALL CAPS words, no more than one "|" separator group per phrase.
- Tags: exactly 13 tags, each max 20 characters, lowercase, letters/numbers/spaces
  only, no duplicates, no single-word repeats of the same stem more than twice.
- Description: 5 short paragraphs - hook, what's included, how to use it,
  file/delivery details, policy note that it is an instant digital download with
  no physical item shipped.
- Never promise refunds, never mention competitors, never use trademarked terms.
- Output valid JSON only.",
    "user_template": "TASK: {{seo_task}}

RESEARCH CONCEPT:
{{research_json}}

PRODUCT BRIEF:
{{idea_json}}

DELIVERABLE FILES:
{{file_manifest}}

Answer with the exact JSON contract for this task.",
    "output_contract": "title  -> {"title": "string", "char_count": 0}
description -> {"description": "string", "paragraph_count": 0}
tags -> {"tags": ["string"], "materials": ["string"]}
keywords -> {"primary": "string", "sub_keywords": ["string"], "long_tail": ["string"]}"
  }
};

return $input.all().map((item) => ({
  json: { ...item.json, prompt_version: PROMPT_VERSION, prompts: PROMPTS },
}));

// Decide what to research. The master controller may pass a seed keyword; when it
// does not, each factory has a sensible default search phrase.
const FACTORY_SEEDS = {
  planner: 'digital planner printable',
  printable: 'printable wall planner',
  canva: 'canva template editable',
  wallart: 'printable wall art set',
  resume: 'resume template modern',
  spreadsheet: 'budget spreadsheet template',
  kids: 'kids printable activity',
  svg: 'svg cut file bundle',
};

const ctx = $input.first().json;
const factory = String(ctx.factory || 'printable').toLowerCase();
const seed = (ctx.seed_keyword || '').trim() || FACTORY_SEEDS[factory] || 'printable digital download';

return [{
  json: {
    ...ctx,
    factory,
    search_keyword: seed,
    etsy_api_base: ctx.etsy_api_base || $('Factory Config').first().json.cfg.ETSY_API_BASE,
    researched_at: new Date().toISOString(),
  },
}];

// Reached when no Etsy key is configured. The aggregator downstream reads the
// two Etsy nodes defensively, so nothing else has to change - this node only
// carries the context forward and states why the signals are absent.
const ctx = $('Normalize Research Input').first().json;
return [{ json: { ...ctx, etsy_signals_skipped: true,
                  etsy_skip_reason: 'ETSY_API_KEY is not set in Factory Config' } }];

// Turn the raw Etsy responses into compact, quantified market signals. Sending
// 100 full listings to the model is wasteful and noisy - sending aggregates is
// cheaper and produces far more grounded answers.
const ctx = $('Normalize Research Input').first().json;

const safe = (nodeName, path) => {
  try {
    const json = $(nodeName).first().json;
    return path(json) || [];
  } catch (e) {
    return [];
  }
};

const listings = safe('Etsy: Search Active Listings', (j) => j.results);
const taxonomy = safe('Etsy: Fetch Taxonomy Nodes', (j) => j.results);

const STOPWORDS = new Set([
  'the', 'and', 'for', 'with', 'your', 'you', 'this', 'that', 'from', 'set',
  'pack', 'pdf', 'png', 'digital', 'download', 'instant', 'printable', 'file',
  'files', 'template', 'templates', 'a', 'of', 'to', 'in', 'on', 'by',
]);

const prices = [];
const tagCount = new Map();
const titleCount = new Map();
let totalSales = 0;
let withSales = 0;

for (const listing of listings) {
  const amount = listing?.price?.amount;
  const divisor = listing?.price?.divisor || 100;
  if (typeof amount === 'number' && divisor) prices.push(amount / divisor);

  if (typeof listing?.num_favorers === 'number') {
    totalSales += listing.num_favorers;
    withSales += 1;
  }

  for (const tag of listing?.tags || []) {
    const key = String(tag).toLowerCase().trim();
    if (key) tagCount.set(key, (tagCount.get(key) || 0) + 1);
  }

  for (const word of String(listing?.title || '').toLowerCase().split(/[^a-z0-9]+/)) {
    if (word.length < 3 || STOPWORDS.has(word)) continue;
    titleCount.set(word, (titleCount.get(word) || 0) + 1);
  }
}

const top = (map, n) => [...map.entries()]
  .sort((a, b) => b[1] - a[1])
  .slice(0, n)
  .map(([value, count]) => ({ value, count }));

prices.sort((a, b) => a - b);
const percentile = (p) => (prices.length ? prices[Math.min(prices.length - 1, Math.floor(prices.length * p))] : null);
const round2 = (n) => (n === null ? null : Math.round(n * 100) / 100);

const signals = {
  search_keyword: ctx.search_keyword,
  factory: ctx.factory,
  competitor_count: listings.length,
  price_usd: {
    min: round2(prices[0] ?? null),
    p25: round2(percentile(0.25)),
    median: round2(percentile(0.5)),
    p75: round2(percentile(0.75)),
    max: round2(prices[prices.length - 1] ?? null),
  },
  average_favourites: withSales ? Math.round(totalSales / withSales) : null,
  top_tags: top(tagCount, 25),
  top_title_words: top(titleCount, 25),
  etsy_categories: taxonomy
    .filter((n) => /craft|paper|party|art|digital|home/i.test(n?.name || ''))
    .slice(0, 25)
    .map((n) => ({ id: n.id, name: n.name, level: n.level })),
  sample_titles: listings.slice(0, 15).map((l) => String(l?.title || '').slice(0, 120)),
  signal_quality: listings.length >= 20 ? 'good' : (listings.length ? 'thin' : 'unavailable'),
};

return [{ json: { ...ctx, market: signals } }];

// Mustache-style renderer for the {{placeholders}} in the prompt templates.
const render = (template, vars) =>
  String(template).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, key) =>
    vars[key] === undefined || vars[key] === null ? '' : String(vars[key]));

const ctx = $input.first().json;
const agent = $('Prompt Library').first().json.prompts.research_ai;

const userPrompt = render(agent.user_template, {
  factory: ctx.factory,
  run_id: ctx.run_id,
  seed_keyword: ctx.search_keyword,
  market_signals_json: JSON.stringify(ctx.market, null, 2),
});

return [{ json: { ...ctx, research_user_prompt: userPrompt } }];

