// One reader for both providers. OpenAI answers with choices[].message.content,
// Gemini with candidates[].content.parts[].text - and a build can target either,
// so every parser in this repo would otherwise need two code paths.
const agentContent = (response) => {
  const openai = response && response.choices && response.choices[0]
    && response.choices[0].message;
  if (openai && typeof openai.content === 'string') return openai.content;
  if (openai && openai.refusal) return '';
  const gemini = response && response.candidates && response.candidates[0];
  if (gemini && gemini.content && Array.isArray(gemini.content.parts)) {
    return gemini.content.parts.map((p) => p && p.text).filter(Boolean).join('');
  }
  return '';
};

// Token counts, normalised to the OpenAI field names the cost tracker records.
const agentUsage = (response) => {
  if (response && response.usage) return response.usage;
  const m = response && response.usageMetadata;
  if (!m) return null;
  return {
    prompt_tokens: m.promptTokenCount || 0,
    completion_tokens: m.candidatesTokenCount || 0,
    total_tokens: m.totalTokenCount || 0,
  };
};

// finish_reason / finishReason, same idea.
const agentFinish = (response) => {
  const openai = response && response.choices && response.choices[0];
  if (openai && openai.finish_reason) return openai.finish_reason;
  const gemini = response && response.candidates && response.candidates[0];
  if (gemini && gemini.finishReason) return String(gemini.finishReason).toLowerCase();
  return 'unknown';
};// Parse + validate the model output against the fixed research contract. The
// node never throws: an invalid answer is routed to the deterministic fallback
// instead of killing the whole run.
const REQUIRED = [
  'product_type', 'category', 'target_customer', 'keyword',
  'sub_keywords', 'difficulty', 'selling_points',
];

const ctx = $('Build Research Prompt').first().json;
const response = $input.first().json;

let research = null;
const errors = [];

try {
  const content = agentContent(response);
  if (!content) throw new Error('OpenAI returned an empty completion');
  research = JSON.parse(content);
} catch (e) {
  errors.push(`parse: ${e.message}`);
}

if (research) {
  for (const key of REQUIRED) {
    if (research[key] === undefined || research[key] === null || research[key] === '') {
      errors.push(`missing field: ${key}`);
    }
  }
  if (!Array.isArray(research.sub_keywords) || research.sub_keywords.length < 5) {
    errors.push('sub_keywords must contain at least 5 entries');
  }
  if (!Array.isArray(research.selling_points) || research.selling_points.length < 3) {
    errors.push('selling_points must contain at least 3 entries');
  }
  if (!['easy', 'medium', 'hard'].includes(String(research.difficulty || '').toLowerCase())) {
    errors.push('difficulty must be easy, medium or hard');
  }
}

return [{
  json: {
    ...ctx,
    research,
    valid: errors.length === 0,
    validation_errors: errors,
    openai_usage: response?.usage || null,
  },
}];

// Etsy caps a tag at 20 characters. Phrases longer than that used to be thrown
// away, and a research package that answered in natural phrases - "printable
// resume template for teachers" - arrived downstream with almost nothing left,
// failing the gate that wants five. Trim to the last whole word instead: the
// shortened phrase is still a real search term.
const toKeyword = (value) => {
  const cleaned = String(value == null ? '' : value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (cleaned.length <= 20) return cleaned;
  const cut = cleaned.slice(0, 20);
  const lastSpace = cut.lastIndexOf(' ');
  return lastSpace > 0 ? cut.slice(0, lastSpace) : '';
};

// A keyword list that is always long enough to work with. Topping up from the
// product's own words beats failing a paid run over the model's brevity, and
// every filler here is a phrase shoppers really type.
const buildKeywords = (sources, context, minimum) => {
  const out = [];
  const push = (value) => {
    const k = toKeyword(value);
    if (k && k.length >= 3 && !out.includes(k)) out.push(k);
  };
  for (const source of sources) for (const value of source || []) push(value);
  if (out.length < (minimum || 5)) {
    const keyword = String(context.keyword || '').trim();
    const factory = String(context.factory || '').trim();
    for (const filler of [
      keyword, factory,
      keyword && `printable ${keyword}`,
      keyword && `${keyword} template`,
      'instant download', 'digital download', 'printable pdf',
      'editable template', 'print at home',
    ]) push(filler);
  }
  return out;
};// Deterministic safety net so a bad completion degrades the run instead of
// failing it. Built purely from the aggregated Etsy signals.
const ctx = $input.first().json;
const market = ctx.market || {};
const tags = (market.top_tags || []).map((t) => t.value);
const words = (market.top_title_words || []).map((t) => t.value);

const keyword = (ctx.search_keyword || 'printable digital download').toLowerCase();
const subKeywords = buildKeywords(
  [tags, words], { keyword, factory: ctx.factory }, 5).slice(0, 13);

return [{
  json: {
    ...ctx,
    research: {
      product_type: ctx.factory,
      category: 'Digital Downloads',
      target_customer: 'Etsy shoppers looking for an instant, ready-to-print digital file',
      keyword,
      sub_keywords: subKeywords,
      difficulty: (market.competitor_count || 0) > 60 ? 'hard' : 'medium',
      selling_points: [
        'Instant download - no waiting and no shipping',
        'Print at home or at any print shop',
        'Clean, modern layout that works on every device',
      ],
      price_suggestion_usd: market?.price_usd?.median || 5,
      market_gap: 'Fallback concept generated from marketplace aggregates only',
      rejected_ideas: [],
    },
    valid: true,
    used_fallback: true,
    fallback_reason: (ctx.validation_errors || []).join('; ') || 'model output rejected',
  },
}];

// Mustache-style renderer for the {{placeholders}} in the prompt templates.
const render = (template, vars) =>
  String(template).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, key) =>
    vars[key] === undefined || vars[key] === null ? '' : String(vars[key]));

const ctx = $input.first().json;
const agent = $('Prompt Library').first().json.prompts.seo_ai;

const userPrompt = render(agent.user_template, {
  seo_task: 'keywords',
  research_json: JSON.stringify(ctx.research, null, 2),
  idea_json: '(not generated yet - this is the research stage)',
  file_manifest: '(not generated yet - this is the research stage)',
});

return [{ json: { ...ctx, seo_user_prompt: userPrompt } }];

